#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0
"""Failure injection for tools/ci/check_be10000_candidate.py.

Builds a small synthetic BE10000 tree without the cross toolchain, but with
the real pieces that matter for the candidate check:

  * failsafe/fsdata.c generated by the real failsafe/html/makefsdatac
    (RC01_WEB_PROFILE=rename-gzip) from the real html/pig pages;
  * a DTB compiled by dtc with the BE10000 identity properties;
  * an ELF32 ARM image whose single LOAD carries that DTB (gzip) and the
    generated responses, packed by the real tools/elftombn_py3.py -v 6.

The reference must pass and produce a candidate directory; each injected
fault (empty/truncated MBN, packer fed a truncated ELF, payload or hash
corruption, wrong board DTB/.config, redundant ENV, broken generated page,
stale fsdata) must be rejected without a candidate directory.

  uv run --offline --no-project python -B test/rc01/test_ci_candidate.py [-v]

Needs node, dtc and fdtget. Optional: RC01_CI_TREE=<built tree> also checks
that tree's real bin/openwrt-ipq9574_xiaomi_be10000-u-boot.mbn and that a
truncated / hash-corrupted copy of it is rejected.
"""

import gzip
import os
import shutil
import struct
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent.parent
CHECKER = ROOT / "tools/ci/check_be10000_candidate.py"
PACKER = ROOT / "tools/elftombn_py3.py"
MBN_NAME = "openwrt-ipq9574_xiaomi_be10000-u-boot.mbn"
TEXT_BASE = 0x4A400000

CONFIG = """CONFIG_ARM=y
CONFIG_SYS_ARCH="arm"
CONFIG_SYS_BOARD="ipq9574"
CONFIG_IPQ9574_XIAOMI_BE10000=y
"""
CFG = """#define CONFIG_SYS_TEXT_BASE 0x4A400000
#define CONFIG_ENV_SIZE CONFIG_ENV_SIZE_MAX
#define CONFIG_ENV_SIZE_MAX (64 << 10)
#define CONFIG_ENV_IS_IN_NAND 1
#define CONFIG_IPQ9574_XIAOMI_BE10000 1
#define CONFIG_LWIP_HTTPD 1
"""
PORT = "port@%d { phy_address = <%d>; phy_type = <%s>; };"


def dts(model="Xiaomi BE10000", machid="0x8050301", port3="6"):
    ports = " ".join(PORT % (i, i + 1, port3 if i == 3 else "6") for i in range(4))
    ports += " port@4 { phy_type = <0xff>; }; port@5 { phy_type = <0xff>; };"
    return ('/dts-v1/;\n/ { model = "%s"; machid = <%s>;\n'
            'config_name = "config@al02-c4", "config-al02-c4", "config@rdp433", "config-rdp433";\n'
            'ess-switch { switch_mac_mode0 = <0x15>; port_phyinfo { %s }; }; };\n'
            % (model, machid, ports))


def fsdata_responses(text):
    out = []
    for line in text.splitlines():
        if line.startswith("static const char data_"):
            body = line[line.index("{") + 1:line.rindex("}")]
            out.append(bytes(int(x, 16) for x in body.split(",")))
    return out


def make_elf(payload):
    """ELF32 ARM ET_DYN: PT_LOAD at TEXT_BASE plus GNU_STACK, like u-boot."""
    off = 0x80
    eh = struct.pack("<16sHHIIIIIHHHHHH", b"\x7fELF\x01\x01\x01" + bytes(9), 3, 40, 1,
                     TEXT_BASE, 52, 0, 0x5000202, 52, 32, 2, 40, 0, 0)
    load = struct.pack("<8I", 1, off, TEXT_BASE, TEXT_BASE, len(payload), len(payload), 7, 0x20)
    stack = struct.pack("<8I", 0x6474E551, 0, 0, 0, 0, 0, 7, 0x10)
    head = eh + load + stack
    return head + bytes(off - len(head)) + payload


class Fixture:
    def __init__(self, base):
        self.base = Path(base)
        self.tree = self.base / "tree"
        self.n = 0

    def gen_fsdata(self, page_edit=None):
        """Run the real makefsdatac on a copy of the real pages."""
        fs = self.tree / "failsafe"
        if fs.exists():
            shutil.rmtree(fs)
        fs.mkdir(parents=True)
        shutil.copytree(ROOT / "failsafe/html", fs / "html",
                        ignore=shutil.ignore_patterns("debug_output", "node_modules", ".*"))
        if page_edit:
            page_edit(fs / "html/pig")
        env = dict(os.environ, RC01_WEB_PROFILE="rename-gzip")
        r = subprocess.run(["./html/makefsdatac"], cwd=fs, env=env,
                           capture_output=True, text=True)
        if r.returncode:
            raise RuntimeError("makefsdatac failed: " + r.stderr[-2000:])
        return (fs / "fsdata.c").read_text()

    def build(self, dts_text=None, page_edit=None, config=CONFIG, cfg=CFG, elf_edit=None):
        self.tree.mkdir(parents=True, exist_ok=True)
        (self.tree / ".config").write_text(config)
        (self.tree / "u-boot.cfg").write_text(cfg)
        fsdata = self.gen_fsdata(page_edit)
        src = self.base / "board.dts"
        src.write_text(dts_text or dts())
        dtb = subprocess.run(["dtc", "-I", "dts", "-O", "dtb", str(src)],
                             capture_output=True, check=True).stdout
        comp = gzip.compress(bytes(64) + dtb, mtime=0)
        (self.tree / "dtb_combined.bin.gz").write_bytes(comp)
        payload = bytes(4096) + comp + b"".join(fsdata_responses(fsdata)) + bytes(4096)
        elf = make_elf(payload)
        if elf_edit:
            elf = elf_edit(elf)
        (self.tree / "u-boot").write_bytes(make_elf(payload))
        work = self.base / "pack"
        work.mkdir(exist_ok=True)
        (work / "u-boot.strip").write_bytes(elf)
        mbn = self.tree / "bin" / MBN_NAME
        mbn.parent.mkdir(exist_ok=True)
        subprocess.run([sys.executable, "-B", str(PACKER), "-f", "u-boot.strip",
                        "-o", str(mbn), "-v", "6", "-a", "ipq9574"],
                       cwd=work, check=True, capture_output=True)
        return mbn


def run_checker(tree, mbn, base):
    out = Path(base) / ("out%d" % len(list(Path(base).glob("out*"))))
    r = subprocess.run([sys.executable, "-B", str(CHECKER), "--tree", str(tree),
                        "--mbn", str(mbn), "--result", str(out / "result.json"),
                        "--candidate-dir", str(out / "candidate"),
                        "--meta", "source_sha=test"],
                       capture_output=True, text=True, timeout=600)
    return r, out / "candidate"


class CandidateCheck(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.fx = Fixture(self.tmp.name)

    def tearDown(self):
        self.tmp.cleanup()

    def accept(self, mbn, tree=None):
        r, cand = run_checker(tree or self.fx.tree, mbn, self.tmp.name)
        self.assertEqual(r.returncode, 0, r.stdout + r.stderr)
        self.assertIn("RESULT: OK", r.stdout)
        sums = (cand / "SHA256SUMS").read_text().split()
        self.assertEqual(sums[1::2], [mbn.name, "manifest.json", "check-result.json"])
        self.assertEqual((cand / mbn.name).read_bytes(), mbn.read_bytes())
        return r

    def reject(self, mbn, stage, tree=None):
        r, cand = run_checker(tree or self.fx.tree, mbn, self.tmp.name)
        self.assertEqual(r.returncode, 1, r.stdout + r.stderr)
        self.assertIn("RESULT: REJECTED", r.stdout)
        self.assertRegex(r.stdout, r"(?m)^%s\s+FAIL" % stage)
        self.assertFalse(cand.exists(), "candidate dir written for a rejected build")
        return r

    def test_reference_and_mbn_faults(self):
        mbn = self.fx.build()
        r = self.accept(mbn)
        self.assertRegex(r.stdout, r"(?m)^web\s+PASS")
        good = mbn.read_bytes()

        def variant(data):
            p = self.fx.tree / "bin" / MBN_NAME
            p.write_bytes(data)
            return p

        with self.subTest("empty"):
            self.reject(variant(b""), "mbn")
        with self.subTest("truncated"):
            self.reject(variant(good[:-4096]), "mbn")
        with self.subTest("trailing data"):
            self.reject(variant(good + bytes(16)), "mbn")
        with self.subTest("payload byte flipped"):
            b = bytearray(good)
            b[-5000] ^= 1
            self.reject(variant(bytes(b)), "mbn")
        with self.subTest("hash table byte flipped"):
            b = bytearray(good)
            ph1 = struct.unpack_from("<8I", good, 52 + 32)
            b[ph1[1] + 48 + 2 * 48 + 7] ^= 0x80      # LOAD digest
            self.reject(variant(bytes(b)), "mbn")

    def test_packer_accepts_truncated_elf_checker_rejects(self):
        # The real packer exits 0 on a short LOAD; the checker must not.
        mbn = self.fx.build(elf_edit=lambda e: e[:-4096])
        self.reject(mbn, "mbn")

    def test_wrong_board(self):
        for name, text in (("model", dts(model="Xiaomi BE7000")),
                           ("machid", dts(machid="0x8050201")),
                           ("port3 not QCA8084", dts(port3="0xff"))):
            with self.subTest(name):
                self.reject(self.fx.build(dts_text=text), "dtb")
        with self.subTest(".config BE7000"):
            cfg = CONFIG.replace("BE10000", "BE7000")
            self.reject(self.fx.build(config=cfg), "config")
        with self.subTest("redundant ENV"):
            self.reject(self.fx.build(cfg=CFG + "#define CONFIG_ENV_OFFSET_REDUND 0x0\n"),
                        "config")
        with self.subTest("ENV 128 KiB"):
            self.reject(self.fx.build(cfg=CFG.replace("64 << 10", "128 << 10")), "config")

    def test_generated_page_failure(self):
        # Broken about.html: generated page scenarios must FAIL in the checker.
        def empty_about(pig):
            (pig / "about.html").write_text("<html></html>")
        r = self.reject(self.fx.build(page_edit=empty_about), "web")
        self.assertIn("FAIL", r.stdout)

    def test_stale_fsdata(self):
        # fsdata.c regenerated after the image: responses are not in LOAD.
        mbn = self.fx.build()

        def edit(pig):
            p = pig / "term.html"
            p.write_text(p.read_text().replace("</body>", "<p>x</p></body>"))
        self.fx.gen_fsdata(edit)
        self.reject(mbn, "web")

    @unittest.skipUnless(os.environ.get("RC01_CI_TREE"), "RC01_CI_TREE not set")
    def test_real_build(self):
        tree = Path(os.environ["RC01_CI_TREE"]).resolve()
        good = (tree / "bin" / MBN_NAME).read_bytes()
        mbn = Path(self.tmp.name) / MBN_NAME
        mbn.write_bytes(good)
        self.accept(mbn, tree)
        mbn.write_bytes(good[:len(good) // 2])
        self.reject(mbn, "mbn", tree)
        b = bytearray(good)
        b[len(good) // 2] ^= 1
        mbn.write_bytes(bytes(b))
        self.reject(mbn, "mbn", tree)


if __name__ == "__main__":
    for tool in ("node", "dtc", "fdtget"):
        if not shutil.which(tool):
            sys.exit("error: %s is required" % tool)
    unittest.main()
